#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as _dt
import importlib.util
import py_compile
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path


VERSION = "0.4.1"

OLD_B64 = {'frontend/src/Pages/LabView.tsx': '', 'frontend/src/Pages/ImageProcessingLabPage.tsx': '', 'frontend/src/components/VisionLabs/ImageProcessing/useImageLabController.ts': '', 'backend/app/services/vision_labs/service/repository.py': '', 'backend/tests/vision_labs/test_lab_service_core.py': ''}
NEW_B64 = {'frontend/src/Pages/LabView.tsx': '', 'frontend/src/Pages/ImageProcessingLabPage.tsx': '', 'frontend/src/components/VisionLabs/ImageProcessing/useImageLabController.ts': '', 'backend/app/services/vision_labs/service/repository.py': '', 'backend/tests/vision_labs/test_lab_service_core.py': '', 'frontend/docs/llm_context/updates/v0041_lab_service_multi_edit.md': ''}
README_B64 = ''

OLD_FILES = {
    key: base64.b64decode(value).decode("utf-8")
    for key, value in OLD_B64.items()
}
NEW_FILES = {
    key: base64.b64decode(value).decode("utf-8")
    for key, value in NEW_B64.items()
}
README_TEXT = base64.b64decode(README_B64).decode("utf-8")


def resolve_roots(frontend_arg, backend_arg):
    cwd = Path.cwd().resolve()

    frontend_candidates = []
    backend_candidates = []

    if frontend_arg:
        frontend_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        backend_candidates.append(Path(backend_arg).expanduser().resolve())

    frontend_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    backend_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            path for path in frontend_candidates
            if (path / "src/Pages/LabView.tsx").exists()
            and (
                path
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).exists()
        ),
        None,
    )

    backend = next(
        (
            path for path in backend_candidates
            if (
                path
                / "app/services/vision_labs/service/repository.py"
            ).exists()
            and (
                path
                / "app/services/vision_labs/service/runtime.py"
            ).exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )

    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def resolve_path(frontend: Path, backend: Path, virtual_path: str) -> Path:
    prefix, rel = virtual_path.split("/", 1)

    if prefix == "frontend":
        return frontend / rel

    if prefix == "backend":
        return backend / rel

    raise RuntimeError(f"Unknown updater path prefix: {prefix}")


def backup(frontend: Path, backend: Path, paths: list[Path]) -> Path:
    stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = (
        frontend
        / ".lambda_updater_backups"
        / f"lab_service_multi_edit_v0041_{stamp}"
    )
    backup_root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue

        try:
            rel = path.relative_to(frontend)
            destination = backup_root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = backup_root / "backend" / rel

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return backup_root


def classify_file(current: str | None, old: str | None, new: str) -> str:
    if current is None:
        return "CREATE"

    if current == new:
        return "OK"

    if old is not None and current == old:
        return "UPDATE"

    return "CONFLICT"


def preflight(frontend: Path, backend: Path):
    conflicts = []

    for virtual_path, new_text in NEW_FILES.items():
        path = resolve_path(frontend, backend, virtual_path)
        current = path.read_text(encoding="utf-8") if path.exists() else None
        old_text = OLD_FILES.get(virtual_path)

        state = classify_file(current, old_text, new_text)

        # Context note is a unique per-update file and is safe to create.
        if virtual_path.startswith("frontend/docs/llm_context/updates/"):
            if state == "CONFLICT":
                conflicts.append(
                    f"{virtual_path}: existing update note differs from v0.4.1"
                )
            continue

        if state == "CONFLICT":
            conflicts.append(
                f"{virtual_path}: current file differs from both the known "
                "v0.4.0 baseline and v0.4.1 target"
            )

    if conflicts:
        raise RuntimeError(
            "Safe update stopped because local changes were detected:\n  - "
            + "\n  - ".join(conflicts)
            + "\nCreate a merge updater instead of overwriting these files."
        )


def scan(frontend: Path, backend: Path) -> int:
    print("=" * 88)
    print("LAMBDA VISION LAB SERVICE MULTI-DEPLOY / EDIT UX V0.4.1")
    print("=" * 88)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflict_count = 0

    for virtual_path, new_text in NEW_FILES.items():
        path = resolve_path(frontend, backend, virtual_path)
        current = path.read_text(encoding="utf-8") if path.exists() else None
        old_text = OLD_FILES.get(virtual_path)
        state = classify_file(current, old_text, new_text)

        if (
            virtual_path.startswith("frontend/docs/llm_context/updates/")
            and current is not None
            and current != new_text
        ):
            state = "CONFLICT"

        print(f"  [{state:8}] {virtual_path}")

        if state == "CONFLICT":
            conflict_count += 1

    readme_path = frontend / "docs/llm_context/README.md"
    if not readme_path.exists():
        print("  [CREATE  ] frontend/docs/llm_context/README.md")
    else:
        print("  [PRESERVE] frontend/docs/llm_context/README.md")

    print()
    print("Behavior introduced:")
    print("  - Multiple independent Lab Services can coexist simultaneously.")
    print("  - service_id omitted => new service; service_id supplied => new version.")
    print("  - Edit a deployed service from its /labs card.")
    print("  - Editing restores pipeline snapshot and exposed checkpoints.")
    print("  - Update Service publishes vN+1 without overwriting history.")
    print("  - Save As New publishes the current stack as another service.")
    print("  - /labs uses compact per-service manual runner cards.")
    print("  - Output previews are fetched lazily only after View is pressed.")
    print("  - Generates an LLM context Markdown map for future code updates.")

    if conflict_count:
        print()
        print(
            f"[WARN] {conflict_count} local conflict(s) detected. "
            "apply will stop rather than overwrite them."
        )

    return 0


def apply(frontend: Path, backend: Path) -> int:
    preflight(frontend, backend)

    targets = [
        resolve_path(frontend, backend, virtual_path)
        for virtual_path in NEW_FILES
    ]

    readme_path = frontend / "docs/llm_context/README.md"
    if readme_path.exists():
        targets.append(readme_path)

    backup_root = backup(frontend, backend, targets)

    for virtual_path, new_text in NEW_FILES.items():
        path = resolve_path(frontend, backend, virtual_path)
        path.parent.mkdir(parents=True, exist_ok=True)

        if not path.exists() or path.read_text(encoding="utf-8") != new_text:
            path.write_text(new_text, encoding="utf-8")
            print(f"[WRITE] {virtual_path}")

    # README is a convention file. If one already exists, preserve it instead
    # of overwriting project-specific documentation.
    if not readme_path.exists():
        readme_path.parent.mkdir(parents=True, exist_ok=True)
        readme_path.write_text(README_TEXT, encoding="utf-8")
        print("[WRITE] frontend/docs/llm_context/README.md")
    else:
        print("[KEEP] frontend/docs/llm_context/README.md")

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def typescript_syntax_check(frontend: Path):
    files = [
        frontend / "src/Pages/LabView.tsx",
        frontend / "src/Pages/ImageProcessingLabPage.tsx",
        frontend
        / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts",
    ]

    node_code = r"""
const fs = require("fs");
const ts = require("typescript");

let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (item) => item.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length > 0) {
    failed = true;
    console.error("TYPE_SCRIPT_ERROR", file);

    for (const item of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(item.messageText, "\n"),
      );
    }
  }
}

process.exit(failed ? 1 : 0);
"""

    return subprocess.run(
        ["node", "-e", node_code, *[str(path) for path in files]],
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )


def backend_smoke(backend: Path):
    code = r"""
import tempfile
from pathlib import Path

from app.services.vision_labs.service.models import (
    LabServiceOutputBinding,
    LabServicePort,
)
from app.services.vision_labs.service.repository import LabServiceRepository

pipeline = {
    "version": 1,
    "nodes": [
        {
            "id": "gray",
            "operator_id": "image.color.grayscale",
            "parameters": {},
            "enabled": True,
        }
    ],
    "connections": [],
    "inputs": {"image": {"node_id": "gray", "port": "image"}},
    "outputs": {"result": {"node_id": "gray", "port": "image"}},
}

inputs = {"image": LabServicePort(type="image")}
outputs = {
    "gray": LabServiceOutputBinding(
        type="image",
        node_id="gray",
        port="image",
    )
}

with tempfile.TemporaryDirectory() as temp:
    repository = LabServiceRepository(Path(temp) / "services")

    first = repository.deploy(
        name="ROI Preprocess",
        lab_type="image_processing",
        inputs=inputs,
        outputs=outputs,
        pipeline_snapshot=pipeline,
    )

    second = repository.deploy(
        name="ROI Preprocess",
        lab_type="image_processing",
        inputs=inputs,
        outputs=outputs,
        pipeline_snapshot=pipeline,
    )

    assert first.service_id != second.service_id
    assert first.version == 1
    assert second.version == 1
    assert len(repository.list_active()) == 2

    updated_first = repository.deploy(
        name="ROI Preprocess Tuned",
        service_id=first.service_id,
        lab_type="image_processing",
        inputs=inputs,
        outputs=outputs,
        pipeline_snapshot=pipeline,
    )

    assert updated_first.service_id == first.service_id
    assert updated_first.version == 2
    assert repository.get(first.service_id).version == 2
    assert repository.get(second.service_id).version == 1
    assert [item.version for item in repository.list_versions(first.service_id)] == [2, 1]

print("LAB_SERVICE_MULTI_EDIT_SMOKE_OK")
print("first=", first.service_id)
print("second=", second.service_id)
print("updated_first_version=", updated_first.version)
"""

    return subprocess.run(
        [sys.executable, "-c", code],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )


def verify(
    frontend: Path,
    backend: Path,
    skip_build: bool = False,
) -> int:
    print("=" * 88)
    print("VERIFY LAMBDA VISION LAB SERVICE MULTI-DEPLOY / EDIT UX V0.4.1")
    print("=" * 88)

    failures = 0

    checks = [
        (
            "LabView uses independent per-service cards",
            "const LabServiceCard" in (
                frontend / "src/Pages/LabView.tsx"
            ).read_text(encoding="utf-8"),
        ),
        (
            "LabView edit action targets editService query",
            "?editService=" in (
                frontend / "src/Pages/LabView.tsx"
            ).read_text(encoding="utf-8"),
        ),
        (
            "LabView output preview is lazy and modal-based",
            "View {outputName}" in (
                frontend / "src/Pages/LabView.tsx"
            ).read_text(encoding="utf-8")
            and "fixed inset-0 z-[100]" in (
                frontend / "src/Pages/LabView.tsx"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Image LAB can load deployed service snapshot for editing",
            "stackFromServiceSnapshot" in (
                frontend
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).read_text(encoding="utf-8")
            and "LabServiceAPI.get(editServiceId)" in (
                frontend
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Image LAB exposes Update Service and Save As New",
            "Update Service" in (
                frontend / "src/Pages/ImageProcessingLabPage.tsx"
            ).read_text(encoding="utf-8")
            and "Save As New" in (
                frontend / "src/Pages/ImageProcessingLabPage.tsx"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Repository allocates unique IDs for independent services",
            "def _allocate_service_id" in (
                backend
                / "app/services/vision_labs/service/repository.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "LLM context update note exists",
            (
                frontend
                / "docs/llm_context/updates/v0041_lab_service_multi_edit.md"
            ).exists(),
        ),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    for path in (
        backend / "app/services/vision_labs/service/repository.py",
        backend / "tests/vision_labs/test_lab_service_core.py",
    ):
        try:
            py_compile.compile(str(path), doraise=True)
            print(f"[OK] Python syntax {path.name}")
        except Exception as exc:
            print(f"[FAIL] Python syntax {path.name}: {exc}")
            failures += 1

    ts_result = typescript_syntax_check(frontend)

    if ts_result.returncode == 0:
        print("[OK] TypeScript syntax/transpile check")
    else:
        combined = (ts_result.stdout + "\n" + ts_result.stderr).strip()

        if "Cannot find module 'typescript'" in combined:
            print(
                "[SKIP] TypeScript transpile check: "
                "typescript module is not available to node"
            )
        else:
            print("[FAIL] TypeScript syntax/transpile check")
            print(combined)
            failures += 1

    smoke = backend_smoke(backend)

    if smoke.returncode == 0:
        print("[OK] Multiple-service/versioning backend smoke")
        if smoke.stdout.strip():
            print(smoke.stdout.strip())
    else:
        print("[FAIL] Multiple-service/versioning backend smoke")
        print((smoke.stdout + "\n" + smoke.stderr).strip())
        failures += 1

    if importlib.util.find_spec("pytest") is None:
        print("[SKIP] pytest not installed; repository smoke already passed")
    else:
        test_path = backend / "tests/vision_labs/test_lab_service_core.py"
        proc = subprocess.run(
            [
                sys.executable,
                "-m",
                "pytest",
                "-q",
                str(test_path.relative_to(backend)),
            ],
            cwd=str(backend),
            text=True,
            capture_output=True,
        )

        if proc.returncode == 0:
            print("[OK] Lab Service regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Lab Service regression tests")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1

    if (
        not skip_build
        and (frontend / "package.json").exists()
        and (frontend / "node_modules").exists()
    ):
        proc = subprocess.run(
            ["npm", "run", "build"],
            cwd=str(frontend),
        )

        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    if failures:
        print(
            f"[FAIL] Verification completed with {failures} issue(s)."
        )
        return 1

    print("[OK] Lab Service v0.4.1 verified.")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "command",
        choices=["scan", "apply", "verify"],
    )
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument(
        "--skip-build",
        action="store_true",
    )
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(
            args.frontend,
            args.backend,
        )

        if args.command == "scan":
            return scan(frontend, backend)

        if args.command == "apply":
            return apply(frontend, backend)

        return verify(
            frontend,
            backend,
            skip_build=args.skip_build,
        )

    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
